const p = $json.body ?? $json;
const required = ['income','course','category','recordId'];
const missing = required.filter(k => p[k] === undefined || p[k] === '');
return [{json:{recordId:p.recordId ?? 'SYNTHETIC-UNKNOWN', input:p, missingFields:missing, safeMode:true, note:'Starter workflow only. Add verified official sources and deterministic rules before use.'}}];

const p=$json.input;
// DEMO RULE ONLY — replace with verified official scheme rules.
const schemes=[{id:'DEMO-SCH-01',name:'Illustrative Merit Support Scheme',ceiling:300000,courses:['B.Tech','B.E.','B.Sc.'],categories:['OBC','SC','ST','General','Other'],rule:'DEMO RULE ONLY: annual family income must be ₹3,00,000 or less; listed undergraduate courses are accepted.',sourceUrl:'https://example.org/demo-scheme-01'},{id:'DEMO-SCH-02',name:'Illustrative Category Support Scheme',ceiling:250000,courses:['B.Tech','B.E.','Diploma'],categories:['OBC','SC','ST'],rule:'DEMO RULE ONLY: annual family income must be ₹2,50,000 or less and category must be OBC, SC, or ST.',sourceUrl:'https://example.org/demo-scheme-02'}];
const results=schemes.map(s=>({schemeId:s.id,name:s.name,status:(Number(p.income)<=s.ceiling&&s.courses.includes(p.course)&&s.categories.includes(p.category))?'POTENTIAL_MATCH':'EXCLUDED',quotedRule:s.rule,sourceUrl:s.sourceUrl,deadline:'UNVERIFIED',evidenceId:'EVD-'+p.recordId+'-'+s.id}));
return [{json:{recordId:$json.recordId,results,unresolved:['Rules and deadlines are illustrative and must be verified against official sources.'],submissionAllowed:false,humanApprovalRequired:true}}];
